import java.util.*;
import java.io.*;

public class Main {
    static long[] reconstruct(long[][] lists) {
        // Write your solution here
        // Return the array, or {-1} if no consistent array exists.
        return new long[]{-1};
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[][] lists = new long[n][];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            int len = (int) in.nval;
            lists[i] = new long[len];
            for (int j = 0; j < len; j++) {
                in.nextToken();
                lists[i][j] = (long) in.nval;
            }
        }
        long[] res = reconstruct(lists);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        System.out.print(sb);
    }
}
